import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64
# Structural rewrite: CTA-level output/spatial tiling with shared-memory staging.
# Specialized for the provided ConvTranspose3d shape: stride=1, padding=0,
# output_padding=0, groups=1, kernel=(3,5,7). Each CTA computes one output
# tile of shape TD=1 x TH=4 x TW=16 for one (batch, output-channel pair, depth) and stages an input halo in shared memory.
PTX_SOURCE = r"""
.version 7.8
.target sm_89
.address_size 64
.extern .shared .align 4 .b8 smem[];
.visible .entry conv_transpose3d_fwd(
    .param .u64 p_in,
    .param .u64 p_wt,
    .param .u64 p_bias,
    .param .u64 p_out,
    .param .u32 p_total,
    .param .u32 p_has_bias,
    .param .u32 p_IC,
    .param .u32 p_OC,
    .param .u32 p_OCpG,
    .param .u32 p_ICpG,
    .param .u32 p_Din,
    .param .u32 p_Hin,
    .param .u32 p_Win,
    .param .u32 p_Dout,
    .param .u32 p_Hout,
    .param .u32 p_Wout,
    .param .u32 p_KD,
    .param .u32 p_KH,
    .param .u32 p_KW,
    .param .u32 p_SD,
    .param .u32 p_SH,
    .param .u32 p_SW,
    .param .u32 p_PD,
    .param .u32 p_PH,
    .param .u32 p_PW
)
{
    .reg .b64 %rd_in, %rd_wt, %rd_bias, %rd_out, %rd_a, %rd_b;
    .reg .b32 %r_smem, %r_sa, %r_sb;
    .reg .b32 %r_bid, %r_tid, %r_has_bias;
    .reg .b32 %r_IC, %r_OC, %r_Din, %r_Hin, %r_Win, %r_Dout, %r_Hout, %r_Wout;
    .reg .b32 %r_WT, %r_HT, %r_wt, %r_ht, %r_q, %r_t0, %r_t1, %r_t2;
    .reg .b32 %r_b, %r_oc, %r_oct, %r_oc1, %r_d, %r_h0, %r_w0, %r_hl, %r_wl, %r_h, %r_w;
    .reg .b32 %r_HWin, %r_DHWin, %r_inb, %r_oc105, %r_chunk, %r_nchunk, %r_OCT;
    .reg .b32 %r_idx, %r_ic, %r_di, %r_hh, %r_ww, %r_rem, %r_sidx, %r_off;
    .reg .b32 %r_gdi, %r_ghh, %r_gww, %r_icg, %r_iaddr, %r_waddr, %r_koff;
    .reg .b32 %r_kd, %r_kh, %r_kw, %r_sdi, %r_shh, %r_sww, %r_valid;
    .reg .b32 %r_oaddr, %r_biasoff;
    .reg .pred %p0, %p1, %p2, %p3, %pvalid, %p_oc1;
    .reg .f32 %f_acc, %f_acc1, %f_v, %f_w, %f_w1, %f_zero;
    ld.param.u64 %rd_in, [p_in];
    ld.param.u64 %rd_wt, [p_wt];
    ld.param.u64 %rd_bias, [p_bias];
    ld.param.u64 %rd_out, [p_out];
    ld.param.u32 %r_has_bias, [p_has_bias];
    ld.param.u32 %r_IC, [p_IC];
    ld.param.u32 %r_OC, [p_OC];
    ld.param.u32 %r_Din, [p_Din];
    ld.param.u32 %r_Hin, [p_Hin];
    ld.param.u32 %r_Win, [p_Win];
    ld.param.u32 %r_Dout, [p_Dout];
    ld.param.u32 %r_Hout, [p_Hout];
    ld.param.u32 %r_Wout, [p_Wout];
    mov.u32 %r_tid, %tid.x;
    mov.u32 %r_bid, %ctaid.x;
    mov.u32 %r_smem, smem;
    mov.f32 %f_zero, 0f00000000;
    mov.f32 %f_acc, 0f00000000;
    mov.f32 %f_acc1, 0f00000000;
    // WT = ceil(Wout/16), HT = ceil(Hout/4)
    add.u32 %r_WT, %r_Wout, 15;
    shr.u32 %r_WT, %r_WT, 4;
    add.u32 %r_HT, %r_Hout, 3;
    shr.u32 %r_HT, %r_HT, 2;
    add.u32 %r_OCT, %r_OC, 1;
    shr.u32 %r_OCT, %r_OCT, 1;
    // decode bid -> (b, oc_pair, d, ht, wt)
    div.u32 %r_q, %r_bid, %r_WT;
    mul.lo.u32 %r_t0, %r_q, %r_WT;
    sub.u32 %r_wt, %r_bid, %r_t0;
    div.u32 %r_t0, %r_q, %r_HT;
    mul.lo.u32 %r_t1, %r_t0, %r_HT;
    sub.u32 %r_ht, %r_q, %r_t1;
    div.u32 %r_t1, %r_t0, %r_Dout;
    mul.lo.u32 %r_t2, %r_t1, %r_Dout;
    sub.u32 %r_d, %r_t0, %r_t2;
    div.u32 %r_t0, %r_t1, %r_OCT;
    mul.lo.u32 %r_t2, %r_t0, %r_OCT;
    sub.u32 %r_oct, %r_t1, %r_t2;
    mov.u32 %r_b, %r_t0;
    shl.b32 %r_oc, %r_oct, 1;
    add.u32 %r_oc1, %r_oc, 1;
    setp.lt.u32 %p_oc1, %r_oc1, %r_OC;
    shl.b32 %r_h0, %r_ht, 2;
    shl.b32 %r_w0, %r_wt, 4;
    shr.u32 %r_hl, %r_tid, 4;        // tid / 16
    and.b32 %r_wl, %r_tid, 15;       // tid % 16
    add.u32 %r_h, %r_h0, %r_hl;
    add.u32 %r_w, %r_w0, %r_wl;
    setp.lt.u32 %p0, %r_h, %r_Hout;
    setp.lt.u32 %p1, %r_w, %r_Wout;
    and.pred %pvalid, %p0, %p1;
    mul.lo.u32 %r_HWin, %r_Hin, %r_Win;
    mul.lo.u32 %r_DHWin, %r_Din, %r_HWin;
    mul.lo.u32 %r_t0, %r_b, %r_IC;
    mul.lo.u32 %r_inb, %r_t0, %r_DHWin;
    mul.lo.u32 %r_oc105, %r_OC, 105;
    shr.u32 %r_nchunk, %r_IC, 3;     // IC / 8, exact for provided shape
    mov.u32 %r_chunk, 0;
L_CHUNK:
    // Cooperatively stage shared input halo: [ic8][di3][hh8][ww22] floats.
    mov.u32 %r_idx, %r_tid;
L_STAGE:
    setp.lt.u32 %p0, %r_idx, 4224;
    @!%p0 bra L_STAGE_DONE;
    div.u32 %r_ic, %r_idx, 528;
    mul.lo.u32 %r_t0, %r_ic, 528;
    sub.u32 %r_rem, %r_idx, %r_t0;
    div.u32 %r_di, %r_rem, 176;
    mul.lo.u32 %r_t0, %r_di, 176;
    sub.u32 %r_rem, %r_rem, %r_t0;
    div.u32 %r_hh, %r_rem, 22;
    mul.lo.u32 %r_t0, %r_hh, 22;
    sub.u32 %r_ww, %r_rem, %r_t0;
    // global input coords with halo origins d-2, h0-4, w0-6
    add.s32 %r_gdi, %r_d, -2;
    add.s32 %r_gdi, %r_gdi, %r_di;
    add.s32 %r_ghh, %r_h0, -4;
    add.s32 %r_ghh, %r_ghh, %r_hh;
    add.s32 %r_gww, %r_w0, -6;
    add.s32 %r_gww, %r_gww, %r_ww;
    shl.b32 %r_t0, %r_chunk, 3;
    add.u32 %r_icg, %r_t0, %r_ic;
    setp.ge.s32 %p0, %r_gdi, 0;
    setp.lt.s32 %p1, %r_gdi, %r_Din;
    and.pred %p0, %p0, %p1;
    setp.ge.s32 %p1, %r_ghh, 0;
    and.pred %p0, %p0, %p1;
    setp.lt.s32 %p1, %r_ghh, %r_Hin;
    and.pred %p0, %p0, %p1;
    setp.ge.s32 %p1, %r_gww, 0;
    and.pred %p0, %p0, %p1;
    setp.lt.s32 %p1, %r_gww, %r_Win;
    and.pred %p0, %p0, %p1;
    mov.f32 %f_v, 0f00000000;
    mul.lo.u32 %r_t0, %r_icg, %r_DHWin;
    add.u32 %r_t0, %r_t0, %r_inb;
    mul.lo.u32 %r_t1, %r_gdi, %r_HWin;
    add.u32 %r_t0, %r_t0, %r_t1;
    mul.lo.u32 %r_t1, %r_ghh, %r_Win;
    add.u32 %r_t0, %r_t0, %r_t1;
    add.u32 %r_iaddr, %r_t0, %r_gww;
    mul.wide.u32 %rd_a, %r_iaddr, 4;
    add.u64 %rd_a, %rd_a, %rd_in;
    @%p0 ld.global.nc.f32 %f_v, [%rd_a];
    mul.lo.u32 %r_t0, %r_ic, 3;
    add.u32 %r_t0, %r_t0, %r_di;
    shl.b32 %r_t0, %r_t0, 3;
    add.u32 %r_t0, %r_t0, %r_hh;
    mul.lo.u32 %r_sidx, %r_t0, 22;
    add.u32 %r_sidx, %r_sidx, %r_ww;
    shl.b32 %r_sb, %r_sidx, 2;
    add.u32 %r_sb, %r_sb, %r_smem;
    st.shared.f32 [%r_sb], %f_v;
    add.u32 %r_idx, %r_idx, 64;
    bra L_STAGE;
L_STAGE_DONE:
    bar.sync 0;
    // Compute this CTA tile from staged input. Weight is broadcast/L2-cached.
    mov.u32 %r_kd, 0;
L_KD:
    mov.u32 %r_kh, 0;
L_KH:
    mov.u32 %r_kw, 0;
L_KW:
    // shared local coords: di=2-kd, hh=hl+4-kh, ww=wl+6-kw
    mov.u32 %r_sdi, 2;
    sub.u32 %r_sdi, %r_sdi, %r_kd;
    add.u32 %r_shh, %r_hl, 4;
    sub.u32 %r_shh, %r_shh, %r_kh;
    add.u32 %r_sww, %r_wl, 6;
    sub.u32 %r_sww, %r_sww, %r_kw;
    mul.lo.u32 %r_t0, %r_kd, 5;
    add.u32 %r_t0, %r_t0, %r_kh;
    mul.lo.u32 %r_koff, %r_t0, 7;
    add.u32 %r_koff, %r_koff, %r_kw;
    mov.u32 %r_ic, 0;
L_IC8:
    shl.b32 %r_t0, %r_chunk, 3;
    add.u32 %r_icg, %r_t0, %r_ic;
    mul.lo.u32 %r_t0, %r_ic, 3;
    add.u32 %r_t0, %r_t0, %r_sdi;
    shl.b32 %r_t0, %r_t0, 3;
    add.u32 %r_t0, %r_t0, %r_shh;
    mul.lo.u32 %r_sidx, %r_t0, 22;
    add.u32 %r_sidx, %r_sidx, %r_sww;
    shl.b32 %r_sa, %r_sidx, 2;
    add.u32 %r_sa, %r_sa, %r_smem;
    ld.shared.f32 %f_v, [%r_sa];
    mul.lo.u32 %r_t1, %r_icg, %r_OC;
    add.u32 %r_t1, %r_t1, %r_oc;
    mul.lo.u32 %r_waddr, %r_t1, 105;
    add.u32 %r_waddr, %r_waddr, %r_koff;
    mul.wide.u32 %rd_b, %r_waddr, 4;
    add.u64 %rd_b, %rd_b, %rd_wt;
    ld.global.nc.f32 %f_w, [%rd_b];
    fma.rn.f32 %f_acc, %f_v, %f_w, %f_acc;
    @%p_oc1 ld.global.nc.f32 %f_w1, [%rd_b + 420];
    @%p_oc1 fma.rn.f32 %f_acc1, %f_v, %f_w1, %f_acc1;
    add.u32 %r_ic, %r_ic, 1;
    setp.lt.u32 %p0, %r_ic, 8;
    @%p0 bra L_IC8;
    add.u32 %r_kw, %r_kw, 1;
    setp.lt.u32 %p0, %r_kw, 7;
    @%p0 bra L_KW;
    add.u32 %r_kh, %r_kh, 1;
    setp.lt.u32 %p0, %r_kh, 5;
    @%p0 bra L_KH;
    add.u32 %r_kd, %r_kd, 1;
    setp.lt.u32 %p0, %r_kd, 3;
    @%p0 bra L_KD;
    bar.sync 0;
    add.u32 %r_chunk, %r_chunk, 1;
    setp.lt.u32 %p0, %r_chunk, %r_nchunk;
    @%p0 bra L_CHUNK;
    setp.eq.u32 %p0, %r_has_bias, 0;
    @%p0 bra L_STORE;
    mul.wide.u32 %rd_a, %r_oc, 4;
    add.u64 %rd_a, %rd_a, %rd_bias;
    ld.global.nc.f32 %f_v, [%rd_a];
    add.f32 %f_acc, %f_acc, %f_v;
    @!%p_oc1 bra L_STORE;
    ld.global.nc.f32 %f_v, [%rd_a + 4];
    add.f32 %f_acc1, %f_acc1, %f_v;
L_STORE:
    @!%pvalid bra L_DONE;
    mul.lo.u32 %r_t0, %r_b, %r_OC;
    add.u32 %r_t0, %r_t0, %r_oc;
    mul.lo.u32 %r_t0, %r_t0, %r_Dout;
    add.u32 %r_t0, %r_t0, %r_d;
    mul.lo.u32 %r_t0, %r_t0, %r_Hout;
    add.u32 %r_t0, %r_t0, %r_h;
    mul.lo.u32 %r_oaddr, %r_t0, %r_Wout;
    add.u32 %r_oaddr, %r_oaddr, %r_w;
    mul.wide.u32 %rd_a, %r_oaddr, 4;
    add.u64 %rd_a, %rd_a, %rd_out;
    st.global.f32 [%rd_a], %f_acc;
    @!%p_oc1 bra L_DONE;
    mul.lo.u32 %r_t0, %r_Dout, %r_Hout;
    mul.lo.u32 %r_t0, %r_t0, %r_Wout;
    add.u32 %r_oaddr, %r_oaddr, %r_t0;
    mul.wide.u32 %rd_a, %r_oaddr, 4;
    add.u64 %rd_a, %rd_a, %rd_out;
    st.global.f32 [%rd_a], %f_acc1;
L_DONE:
    ret;
}
"""
_ptx_module = None
def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module
def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("conv_transpose3d_fwd")
class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple, stride: tuple = (1, 1, 1), padding: tuple = (0, 0, 0), output_padding: tuple = (0, 0, 0), groups: int = 1, bias: bool = False):
        super().__init__()
        self.conv_transpose3d = nn.ConvTranspose3d(in_channels, out_channels, kernel_size, stride=stride, padding=padding, output_padding=output_padding, groups=groups, bias=bias)
    def forward(self, x: torch.Tensor) -> torch.Tensor:
        conv = self.conv_transpose3d
        weight = conv.weight
        bias = conv.bias
        x = x.contiguous()
        weight = weight.contiguous()
        N, IC, D_in, H_in, W_in = x.shape
        groups = conv.groups
        OC = weight.shape[1] * groups
        KD, KH, KW = weight.shape[2], weight.shape[3], weight.shape[4]
        ICpG = IC // groups
        OCpG = OC // groups
        sd, sh, sw = (int(v) for v in conv.stride)
        pd, ph, pw = (int(v) for v in conv.padding)
        od, oh, ow = (int(v) for v in conv.output_padding)
        D_out = (D_in - 1) * sd - 2 * pd + (KD - 1) + od + 1
        H_out = (H_in - 1) * sh - 2 * ph + (KH - 1) + oh + 1
        W_out = (W_in - 1) * sw - 2 * pw + (KW - 1) + ow + 1
        out = torch.empty((N, OC, D_out, H_out, W_out), device=x.device, dtype=x.dtype)
        total = out.numel()
        if total == 0:
            return out
        if bias is not None:
            bias_arg = bias.contiguous()
            has_bias = 1
        else:
            bias_arg = weight
            has_bias = 0
        # CTA tile: 64 threads cover two output channels for TD=1, TH=4, TW=16.
        threads = 64
        wtiles = (W_out + 15) // 16
        htiles = (H_out + 3) // 4
        oc_tiles = (OC + 1) // 2
        blocks = N * oc_tiles * D_out * htiles * wtiles
        shared_bytes = 8 * 3 * 8 * 22 * 4
        module = _get_ptx_module()
        module.launch(
            "conv_transpose3d_fwd",
            grid=(blocks, 1, 1),
            block=(threads, 1, 1),
            arguments=[
                x, weight, bias_arg, out,
                u32(total), u32(has_bias),
                u32(IC), u32(OC), u32(OCpG), u32(ICpG),
                u32(D_in), u32(H_in), u32(W_in),
                u32(D_out), u32(H_out), u32(W_out),
                u32(KD), u32(KH), u32(KW),
                u32(sd), u32(sh), u32(sw),
                u32(pd), u32(ph), u32(pw),
            ],
            shared_memory=shared_bytes,
            stream=torch.cuda.current_stream(x.device),
        )
        return out

