    .reg .b32 %r_ocloc, %r_icbase;
    .reg .b32 %r_HWin, %r_DHWin, %r_KHKW, %r_DKHKW, %r_wtstep;
    .reg .b32 %r_inbase, %r_wtbase;
    .reg .b32 %r_kd, %r_kh, %r_kw, %r_ic;
    .reg .b32 %r_dbase, %r_dhbase, %r_wtkd, %r_wtkh;
    .reg .b32 %r_st, %r_sq, %r_sr;
    .reg .b32 %r_t0, %r_t1, %r_t2;
    .reg .pred %p0;
    .reg .f32 %f_acc, %f_v, %f_w;

    ld.param.u64 %rd_in, [p_in];
    ld.param.u64 %rd_wt, [p_wt];
    ld.param.u64 %rd_bias, [p_bias];
    ld.param.u64 %rd_out, [p_out];
    ld.param.u32 %r_total, [p_total];
    ld.param.u32 %r_has_bias, [p_has_bias];
    ld.param.u32 %r_IC, [p_IC];
    ld.param.u32 %r_OC, [p_OC];
    ld.param.u32 %r_OCpG, [p_OCpG];
    ld.param.u32 %r_ICpG, [p_ICpG];
    ld.param.u32 %r_Din, [p_Din];
    ld.param.u32 %r_Hin, [p_Hin];
    ld.param.u32 %r_Win, [p_Win];
    ld.param.u32 %r_Dout, [p_Dout];
    ld.param.u32 %r_Hout, [p_Hout];
    ld.param.u32 %r_Wout, [p_Wout];
    ld.param.u32 %r_KD, [p_KD];
    ld.param.u32 %r_KH, [p_KH];
    ld.param.u32 %r_KW, [p_KW];
    ld.param.u32 %r_SD, [p_SD];
    ld.param.u32 %r_SH, [p_SH];
    ld.param.u32 %r_SW, [p_SW];
    ld.param.u32 %r_PD, [p_PD];
    ld.param.u32 %r_PH, [p_PH];
    ld.param.u32 %r_PW, [p_PW];

    mov.u32 %r_t0, %ctaid.x;
    mov.u32 %r_t1, %ntid.x;
    mov.u32 %r_t2, %tid.x;
    mad.lo.u32 %r_tid, %r_t0, %r_t1, %r_t2;

    setp.ge.u32 %p0, %r_tid, %r_total;
    @%p0 bra L_DONE;

    // decode linear output index -> (b, oc, d, h, w), w fastest
    div.u32 %r_t0, %r_tid, %r_Wout;
    mul.lo.u32 %r_t1, %r_t0, %r_Wout;
    sub.u32 %r_w, %r_tid, %r_t1;
    div.u32 %r_t1, %r_t0, %r_Hout;
    mul.lo.u32 %r_t2, %r_t1, %r_Hout;
    sub.u32 %r_h, %r_t0, %r_t2;
    div.u32 %r_t2, %r_t1, %r_Dout;
    mul.lo.u32 %r_t0, %r_t2, %r_Dout;
    sub.u32 %r_d, %r_t1, %r_t0;
    div.u32 %r_t0, %r_t2, %r_OC;
    mul.lo.u32 %r_t1, %r_t0, %r_OC;
    sub.u32 %r_oc, %r_t2, %r_t1;
    mov.u32 %r_b, %r_t0;

    // group decomposition
    div.u32 %r_t0, %r_oc, %r_OCpG;
    mul.lo.u32 %r_t1, %r_t0, %r_OCpG;
    sub.u32 %r_ocloc, %r_oc, %r_t1;
    mul.lo.u32 %r_icbase, %r_t0, %r_ICpG;

    // strides (in elements)
    mul.lo.u32 %r_HWin, %r_Hin, %r_Win;
    mul.lo.u32 %r_DHWin, %r_Din, %r_HWin;
    mul.lo.u32 %r_KHKW, %r_KH, %r_KW;
    mul.lo.u32 %r_DKHKW, %r_KD, %r_KHKW;
    mul.lo.u32 %r_wtstep, %r_OCpG, %r_DKHKW;

    // base offsets
    mul.lo.u32 %r_t0, %r_b, %r_IC;
    add.u32 %r_t0, %r_t0, %r_icbase;
    mul.lo.u32 %r_inbase, %r_t0, %r_DHWin;
    mul.lo.u32 %r_t0, %r_icbase, %r_wtstep;
    mul.lo.u32 %r_t1, %r_ocloc, %r_DKHKW;
    add.u32 %r_wtbase, %r_t0, %r_t1;

    // byte steps for the input-channel inner loop
    mul.wide.u32 %rd_istep, %r_DHWin, 4;
    mul.wide.u32 %rd_wstep, %r_wtstep, 4;

    mov.f32 %f_acc, 0f00000000;

    mov.u32 %r_kd, 0;
L_KD:
    add.u32 %r_t0, %r_d, %r_PD;
    sub.s32 %r_st, %r_t0, %r_kd;
    setp.lt.s32 %p0, %r_st, 0;
    @%p0 bra L_KD_NEXT;
    div.s32 %r_sq, %r_st, %r_SD;
    mul.lo.s32 %r_sr, %r_sq, %r_SD;
    sub.s32 %r_sr, %r_st, %r_sr;
    setp.ne.s32 %p0, %r_sr, 0;
    @%p0 bra L_KD_NEXT;
    setp.ge.s32 %p0, %r_sq, %r_Din;
    @%p0 bra L_KD_NEXT;
    mul.lo.u32 %r_dbase, %r_sq, %r_HWin;
    mul.lo.u32 %r_wtkd, %r_kd, %r_KHKW;

    mov.u32 %r_kh, 0;
L_KH:
    add.u32 %r_t0, %r_h, %r_PH;
    sub.s32 %r_st, %r_t0, %r_kh;
    setp.lt.s32 %p0, %r_st, 0;
    @%p0 bra L_KH_NEXT;
    div.s32 %r_sq, %r_st, %r_SH;
    mul.lo.s32 %r_sr, %r_sq, %r_SH;
    sub.s32 %r_sr, %r_st, %r_sr;
    setp.ne.s32 %p0, %r_sr, 0;
    @%p0 bra L_KH_NEXT;
    setp.ge.s32 %p0, %r_sq, %r_Hin;
    @%p0 bra L_KH_NEXT;
    mul.lo.u32 %r_t0, %r_sq, %r_Win;
    add.u32 %r_dhbase, %r_dbase, %r_t0;
    mul.lo.u32 %r_t0, %r_kh, %r_KW;
    add.u32 %r_wtkh, %r_wtkd, %r_t0;

    mov.u32 %r_kw, 0;
L_KW:
    add.u32 %r_t0, %r_w, %r_PW;
    sub.s32 %r_st, %r_t0, %r_kw;
    setp.lt.s32 %p0, %r_st, 0;
    @%p0 bra L_KW_NEXT;
    div.s32 %r_sq, %r_st, %r_SW;
    mul.lo.s32 %r_sr, %r_sq, %r_SW;
    sub.s32 %r_sr, %r_st, %r_sr;
    setp.ne.s32 %p0, %r_sr, 0;
    @%p0 bra L_KW_NEXT;
    setp.ge.s32 %p0, %r_sq, %r_Win;
    @%p0 bra L_KW_NEXT;

    // input element address
    add.u32 %r_t0, %r_dhbase, %r_sq;
    add.u32 %r_t0, %r_t0, %r_inbase;
    mul.wide.u32 %rd_pi, %r_t0, 4;
    add.u64 %rd_pi, %rd_pi, %rd_in;
    // weight element address
    add.u32 %r_t1, %r_wtkh, %r_kw;
    add.u32 %r_t1, %r_t1, %r_wtbase;
    mul.wide.u32 %rd_pw, %r_t1, 4;
    add.u64 %rd_pw, %rd_pw, %rd_wt;

    mov.u32 %r_ic, %r_ICpG;
L_IC:
    ld.global.nc.f32 %f_v, [%rd_pi];
    ld.global.nc.f32 %f_w, [%rd_pw];
    fma.rn.f32 %f_acc, %f_v, %f_w, %f_acc;
    add.u64 %rd_pi, %rd_pi, %rd_istep;
    add.u64 %rd_pw, %rd_pw, %rd_wstep;
    sub.u32 %r_ic, %r_ic, 1;
    setp.ne.u32 %p0, %r_ic, 0;
    @%p0 bra L_IC;

L_KW_NEXT:
    add.u32 %r_kw, %r_kw, 1;
    setp.lt.u32 %p0, %r_kw, %r_KW;
    @%p0 bra L_KW;

L_KH_NEXT:
    add.u32 %r_kh, %r_kh, 1;
    setp.lt.u32 %p0, %r_kh, %r_KH;
    @%p0 bra L_KH;

L_KD_NEXT:
    add.u32 %r_kd, %r_kd, 1;
    setp.lt.u32 %p0, %r_kd, %r_KD;
    @%p0 bra L_KD;

    // optional bias
    setp.eq.u32 %p0, %r_has_bias, 0;
    @%p0 bra L_STORE;
    mul.wide.u32 %rd_tmp, %r_oc, 4;
    add.u64 %rd_tmp, %rd_tmp, %rd_bias;
    ld.global.nc.f32 %f_v, [%rd_tmp];
    add.f32 %f_acc, %f_acc, %f_v;

L_STORE:
    mul.wide.u32 %rd_tmp, %r_tid, 4;
    add.u64 %rd_tmp, %rd_tmp, %rd_out;
    st.global.f32 [%rd_tmp], %f_acc;

L_DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("conv_transpose3d_fwd")

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple, stride: tuple = (1, 1, 1), padding: tuple = (0, 0, 0), output_padding: tuple = (0, 0, 0), groups: int = 1, bias: bool = False):
        super().__init__()
        self.conv_transpose3d = nn.ConvTranspose3d(in_channels, out_channels, kernel_size, stride=stride, padding=padding, output_padding=output_padding, groups=groups, bias=bias)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        conv = self.conv_transpose3d
        weight = conv.weight
        bias = conv.bias

        x = x.contiguous()
        weight = weight.contiguous()

        N, IC, D_in, H_in, W_in = x.shape
        groups = conv.groups
        OC = weight.shape[1] * groups
        KD, KH, KW = weight.shape[2], weight.shape[3], weight.shape[4]
        ICpG = IC // groups
        OCpG = OC // groups
        sd, sh, sw = (int(v) for v in conv.stride)
        pd, ph, pw = (int(v) for v in conv.padding)
        od, oh, ow = (int(v) for v in conv.output_padding)

        D_out = (D_in - 1) * sd - 2 * pd + (KD - 1) + od + 1
        H_out = (H_in - 1) * sh - 2 * ph + (KH - 1) + oh + 1
        W_out = (W_in - 1) * sw - 2 * pw + (KW - 1) + ow + 1

        out = torch.empty((N, OC, D_out, H_out, W_out), device=x.device, dtype=x.dtype)
        total = out.numel()
        if total == 0:
            return out

        if bias is not None:
            bias_arg = bias.contiguous()
            has_bias = 1
        else:
            bias_arg = weight
            has_bias = 0

        threads = 256
        blocks = (total + threads - 1) // threads

        module = _get_ptx_module()
        module.launch(
            "conv_transpose3d_fwd",
            grid=(blocks, 1, 1),
            block=(threads, 1, 1),
            arguments=[
                x, weight, bias_arg, out,
                u32(total), u32(has_bias),
                u32(IC), u32(OC), u32(OCpG), u32(ICpG),
                u32(D_in), u32(H_in), u32(W_in),
                u32(D_out), u32(H_out), u32(W_out),
                u32(KD), u32(KH), u32(KW),
                u32(sd), u32(sh), u32(sw),
                u32(pd), u32(ph), u32(pw),
            ],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return out
